package com.example.jpademo;

import com.example.jpademo.entity.Customer;
import com.example.jpademo.repository.CustomerRepository;
import org.springframework.boot.CommandLineRunner;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;

@SpringBootApplication
public class DemoApplication {

    public static void main(String[] args) {
        SpringApplication.run(DemoApplication.class, args);
    }

    @Bean
    CommandLineRunner seedData(CustomerRepository customers) {
        return args -> {
            customers.save(new Customer("Alice", "alice@example.com"));
            customers.save(new Customer("Bob", "bob@example.com"));

            customers.findAll().forEach(System.out::println);
            customers.findByEmail("alice@example.com")
                    .ifPresent(c -> System.out.println("Found by email: " + c));
        };
    }
}

package com.example.jpademo.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

@Entity
@Table(name = "customers")
public class Customer {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String name;

    @Column(nullable = false, unique = true)
    private String email;

    protected Customer() {
    }

    public Customer(String name, String email) {
        this.name = name;
        this.email = email;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    @Override
    public String toString() {
        return "Customer{id=" + id + ", name='" + name + "', email='" + email + "'}";
    }
}

package com.example.jpademo.repository;

import com.example.jpademo.entity.Customer;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface CustomerRepository extends JpaRepository<Customer, Long> {

    Optional<Customer> findByEmail(String email);

    List<Customer> findByNameContainingIgnoreCase(String name);
}

package com.example.jpademo;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.jpademo.entity.Customer;
import com.example.jpademo.repository.CustomerRepository;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;

@DataJpaTest
class CustomerRepositoryTest {

    @Autowired
    private CustomerRepository customers;

    @Test
    void savesAndFindsByEmail() {
        customers.save(new Customer("Alice", "alice@example.com"));

        assertThat(customers.findByEmail("alice@example.com"))
                .isPresent()
                .get()
                .extracting(Customer::getName)
                .isEqualTo("Alice");
    }

    @Test
    void findsByNameContainingIgnoreCase() {
        customers.save(new Customer("Alice", "alice@example.com"));
        customers.save(new Customer("Bob", "bob@example.com"));

        List<Customer> found = customers.findByNameContainingIgnoreCase("ali");

        assertThat(found).hasSize(1);
        assertThat(found.get(0).getEmail()).isEqualTo("alice@example.com");
    }
}

package com.example.jpademo;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class DemoApplication {

    public static void main(String[] args) {
        SpringApplication.run(DemoApplication.class, args);
    }
}

package com.example.jpademo;

import com.example.jpademo.entity.Customer;
import com.example.jpademo.repository.CustomerRepository;
import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

@Component
public class DataInitializer implements CommandLineRunner {

    private final CustomerRepository customers;

    public DataInitializer(CustomerRepository customers) {
        this.customers = customers;
    }

    @Override
    public void run(String... args) {
        if (customers.count() > 0) {
            return;
        }

        customers.save(new Customer("Alice", "alice@example.com"));
        customers.save(new Customer("Bob", "bob@example.com"));

        customers.findAll().forEach(System.out::println);
        customers.findByEmail("alice@example.com")
                .ifPresent(c -> System.out.println("Found by email: " + c));
    }
}
